#include "knowledge_ai_host.hpp"
#include "knowledge_legacy.hpp"
#include "ai_settings_model.hpp"
#include "research_runs_model.hpp"
#include <QFile>
#include <QDir>
#include <QSaveFile>
#include <QLockFile>
#include <QRegularExpression>
namespace knowledgeAiHost {
static void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
static QByteArray bytes(const QJsonObject&o){return QJsonDocument(o).toJson(QJsonDocument::Compact);}
QString identity(const QJsonObject&d){auto kind=d.value("kind").toString(),id=d.value("id").toString();need((kind=="docs"||kind=="collections")&&!id.isEmpty()&&id.size()<=200,"需要精确的来源类型与ID");return kind+":"+id;}
QJsonObject reference(const QJsonObject&d){identity(d);auto row=d.value("row").toObject();need(d.value("row").isObject()&&row.value("id")==d.value("id")&&row.value("text").isString()&&(!row.contains("originalText")||row.value("originalText").isString()),"来源身份或完整正文无效");QJsonObject extra;if(d.contains("legacyKnowledge")){knowledgeLegacy::bound(d);extra["legacyKnowledgeSha256"]=researchRuns::fingerprint(d["legacyKnowledge"]);}QJsonObject result{{"kind",d.value("kind")},{"id",d.value("id")},{"bodySha256",aiSettings::hash((row.value("text").toString()+QChar(0)+row.value("originalText").toString()).toUtf8())},{"rowSha256",researchRuns::fingerprint(row)},{"textBytes",row.value("text").toString().toUtf8().size()},{"originalTextBytes",row.value("originalText").toString().toUtf8().size()}};for(auto key:extra.keys())result[key]=extra[key];return result;}
QJsonArray catalogue(const QJsonArray&input){need(input.size()<=10000&&QJsonDocument(input).toJson(QJsonDocument::Compact).size()<=32*1024*1024,"本机资料目录过大，未截断");QSet<QString> ids;QJsonArray refs;for(auto v:input){need(v.isObject(),"资料描述符必须为对象");auto d=v.toObject();auto key=identity(d);need(!ids.contains(key),"同来源类型的ID重复，不能选择");ids.insert(key);refs.append(reference(d));}return refs;}
QJsonObject selection(const QJsonArray&input){need(input.size()<=20&&QJsonDocument(input).toJson(QJsonDocument::Compact).size()<=512*1024,"选择超过20项或512KiB，未截断");auto refs=catalogue(input);for(auto v:input)need(!v.toObject().value("row").toObject().value("text").toString().trimmed().isEmpty(),"所选材料没有完整可用本机正文");return {{"materials",input},{"manifest",refs},{"count",input.size()}};}
QJsonObject confirm(const QJsonObject&held,const QJsonArray&current){auto expected=selection(held.value("materials").toArray());need(expected==held&&!held.value("materials").toArray().isEmpty(),"先明确选择完整资料");catalogue(current);QHash<QString,QJsonObject> map;for(auto v:current){auto d=v.toObject();map[identity(d)]=d;}for(auto v:held.value("manifest").toArray()){auto ref=v.toObject();auto key=identity(ref);need(map.contains(key)&&reference(map[key])==ref,"来源已变化或缺失；原冻结材料保留，请重新选择");}return held;}
QJsonObject draft(const QString&q,const QJsonObject&s,const QJsonObject&p,const QString&search,int view,const QString&archive){need(q.toUtf8().size()<=8000&&search.toUtf8().size()<=2000&&view>=0&&view<=2,"草稿问题或阅读位置超过边界");need(archive.isEmpty()||QRegularExpression("^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\\.json$").match(archive).hasMatch(),"档案必须为私有目录内的精确文件名");need(selection(s.value("materials").toArray())==s,"选择清单与完整材料不一致");QJsonObject out{{"schema","native-knowledge-ai-host-draft/v1"},{"question",q},{"selection",s},{"preferences",aiSettings::preferences(p)},{"search",search},{"view",view},{"archive",archive}};need(bytes(out).size()<=DraftLimit,"完整草稿过大，未截断");return out;}
QJsonObject validate(const QJsonObject&s){auto expected=draft(s.value("question").toString(),s.value("selection").toObject(),s.value("preferences").toObject(),s.value("search").toString(),s.value("view").toInt(-1),s.value("archive").toString());need(expected==s,"草稿字段、来源摘要或模式无效");return s;}
QByteArray Store::readBytes()const{QFile f(QDir(directory).filePath("draft.json"));need(f.open(QIODevice::ReadOnly)&&f.size()>0&&f.size()<=DraftLimit,"私有完整草稿不可读或过大");auto b=f.read(DraftLimit+1);need(b.size()<=DraftLimit,"私有完整草稿过大");QJsonParseError e;auto d=QJsonDocument::fromJson(b,&e);need(e.error==QJsonParseError::NoError&&d.isObject(),"私有草稿JSON无效");validate(d.object());return b;}
QJsonObject Store::marker()const{if(!QFile::exists(QDir(directory).filePath("draft.json")))return {};auto b=readBytes();return {{"schema","knowledge-ai-host-marker/v1"},{"sha256",aiSettings::hash(b)}};}
QJsonObject Store::read(const QJsonObject&m)const{need(m.keys()==QStringList{"schema","sha256"}&&m.value("schema")=="knowledge-ai-host-marker/v1"&&QRegularExpression("^[a-f0-9]{64}$").match(m.value("sha256").toString()).hasMatch(),"短状态标识无效");auto b=readBytes();need(aiSettings::hash(b)==m.value("sha256"),"草稿摘要已变化；未恢复替代版本");return QJsonDocument::fromJson(b).object();}
QJsonObject Store::save(const QJsonObject&s,const QJsonObject&expected)const{auto checked=validate(s);need(!directory.isEmpty()&&QDir().mkpath(directory),"私有目录不可用");QLockFile lock(QDir(directory).filePath("draft.lock"));lock.setStaleLockTime(0);need(lock.tryLock(0),"草稿正被另一个页面写入");need(marker()==expected,"草稿版本已变化，未覆盖其他修改");auto b=bytes(checked);QSaveFile f(QDir(directory).filePath("draft.json"));f.setDirectWriteFallback(false);need(f.open(QIODevice::WriteOnly)&&f.write(b)==b.size()&&f.commit(),"完整草稿保存失败");QJsonObject result{{"schema","knowledge-ai-host-marker/v1"},{"sha256",aiSettings::hash(b)}};need(read(result)==checked,"草稿写后核对失败");return result;}
}
